      await token.connect(user1).stake(ethers.parseEther("500"));

      expect(await token.stakedBalance(user1.address)).to.equal(
        ethers.parseEther("500")
      );
      expect(await token.totalStaked()).to.equal(ethers.parseEther("500"));
